 insert into public.profiles(id,username,full_name,preferred_level) values(new.id,final_username,coalesce(new.raw_user_meta_data->>'full_name','DataQuest learner'),'mid-senior'); return new;
 insert into public.lesson_progress(user_id,lesson_id) values(auth.uid(),p_lesson_id);
 insert into public.quiz_attempts(user_id,lesson_id,correct) values(auth.uid(),p_lesson_id,p_correct); update public.profiles set xp=current_xp+bonus where id=auth.uid(); return query select current_xp+bonus;
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj1','data-science','junior','Introducción a la ciencia de datos','Qué hace un data scientist y cómo transforma preguntas en evidencia.','Concepto',6,20,1,'{"objective":"Traducir una pregunta de negocio en una hipótesis medible y un plan de análisis.","explanation":"La ciencia de datos combina contexto de negocio, estadística, programación y comunicación. El flujo típico es: definir la pregunta, obtener datos, explorar, modelar cuando aporta valor y comunicar una decisión.","exampleTitle":"Caso: churn","example":"Una empresa quiere reducir bajas. Primero define qué significa “baja”, el horizonte de predicción y qué acción tomará con el resultado.","challenge":"Escribe una pregunta medible para explicar por qué aumentó el churn.","quiz":{"question":"¿Cuál es la idea clave de introducción a la ciencia de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj2','data-science','junior','Tipos de datos','Clasifica datos numéricos, categóricos y temporales.','Quiz',6,20,2,'{"objective":"Reconocer variables numéricas, categóricas, booleanas y temporales para elegir tratamientos correctos.","explanation":"El tipo de dato determina qué operaciones tienen sentido. Una fecha permite ordenar y calcular intervalos; una categoría se puede contar o codificar; un valor numérico puede agregarse.","exampleTitle":"Dataset de clientes","example":"edad=34 es numérico, plan=Pro es categórico y signup_date es temporal.","challenge":"Clasifica cinco columnas de un dataset antes de analizarlas.","quiz":{"question":"¿Cuál es la idea clave de tipos de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj3','data-science','junior','Estadística básica','Media, mediana, dispersión y cómo leerlas.','Quiz',6,20,3,'{"objective":"Interpretar centro, dispersión y distribución sin confundir una medida con toda la historia.","explanation":"La media es sensible a valores extremos; la mediana es más robusta. La desviación estándar resume dispersión, pero siempre conviene mirar la distribución.","exampleTitle":"Ingresos","example":"Si 9 clientes gastan 100 y uno gasta 10.000, la media se dispara mientras la mediana permanece cerca del comportamiento típico.","challenge":"Explica qué medida usarías para resumir salarios muy sesgados.","quiz":{"question":"¿Cuál es la idea clave de estadística básica?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj4','data-science','junior','Limpieza de datos','Detecta valores nulos, duplicados y formatos inconsistentes.','Práctica',6,20,4,'{"objective":"Detectar y corregir nulos, duplicados, formatos inconsistentes y valores imposibles.","explanation":"Limpiar no significa borrar filas automáticamente. Primero cuantifica el problema, decide una regla reproducible y conserva trazabilidad de las transformaciones.","exampleTitle":"Fechas de ventas","example":"“2026/01/02”, “02-01-2026” y una fecha futura pueden representar problemas distintos.","challenge":"Propón una regla para normalizar fechas y validar valores fuera de rango.","quiz":{"question":"¿Cuál es la idea clave de limpieza de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj5','data-science','junior','Introducción a Python','Variables, funciones, listas y estructuras útiles para datos.','Código',6,20,5,'{"objective":"Usar variables, colecciones, funciones y condicionales para automatizar tareas de datos.","explanation":"Python permite expresar transformaciones de forma legible. Las funciones ayudan a evitar duplicación y a probar pequeñas piezas de lógica.","exampleTitle":"Función de descuento","example":"def precio_final(precio, descuento): return precio*(1-descuento)","challenge":"Crea una función que reciba una lista de ventas y devuelva el total.","quiz":{"question":"¿Cuál es la idea clave de introducción a python?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj6','data-science','junior','Pandas básico','Carga, filtra, agrupa y transforma un dataset.','Práctica',6,20,6,'{"objective":"Seleccionar, filtrar, agrupar y transformar un DataFrame.","explanation":"Pandas representa datos tabulares y ofrece operaciones vectorizadas. Un buen hábito es inspeccionar tipos y tamaños antes de transformar.","exampleTitle":"Agrupar ventas","example":"df.groupby(\\\"country\\\")[\\\"revenue\\\"].sum()","challenge":"Obtén ventas por país y ordena de mayor a menor.","quiz":{"question":"¿Cuál es la idea clave de pandas básico?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj7','data-science','junior','Visualización básica','Elige el gráfico correcto para cada pregunta.','Gráfico',6,20,7,'{"objective":"Elegir un gráfico según la pregunta, no según el gráfico que se vea más llamativo.","explanation":"Líneas ayudan con tendencias temporales; barras comparan categorías; dispersión muestra relación entre dos variables numéricas.","exampleTitle":"Ventas mensuales","example":"Un gráfico de líneas revela una tendencia; un gráfico de barras facilita comparar regiones.","challenge":"Elige un gráfico para comparar ventas de 6 regiones y justifica la elección.","quiz":{"question":"¿Cuál es la idea clave de visualización básica?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsj8','data-science','junior','Primer modelo de ML','Entrena y evalúa un modelo sencillo de predicción.','Proyecto',6,40,8,'{"objective":"Separar datos, entrenar un modelo sencillo y evaluar generalización.","explanation":"Un modelo aprende patrones del conjunto de entrenamiento. El conjunto de prueba debe permanecer aislado para estimar cómo funcionará con datos no vistos.","exampleTitle":"Predicción de churn","example":"features → train/test split → modelo → predicción → métrica","challenge":"Diseña un flujo mínimo para predecir si un cliente cancelará.","quiz":{"question":"¿Cuál es la idea clave de primer modelo de ml?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm1','data-science','mid-senior','Feature engineering','Crea variables que ayuden al modelo a capturar señal.','Práctica',6,20,1,'{"objective":"Crear variables que representen mejor la señal disponible sin introducir fuga de información.","explanation":"Una buena feature resume comportamiento relevante. Debe calcularse con información disponible en el momento de la predicción y validarse fuera de muestra.","exampleTitle":"Recencia de compra","example":"days_since_last_purchase puede ser más informativa que usar directamente decenas de transacciones históricas.","challenge":"Propón tres features para predecir recompra y verifica que no usen información futura.","quiz":{"question":"¿Cuál es la idea clave de feature engineering?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm2','data-science','mid-senior','Modelos supervisados','Compara regresión, árboles y ensembles.','Código',6,20,2,'{"objective":"Comparar algoritmos supervisados según tipo de objetivo, datos, interpretabilidad y coste.","explanation":"Regresión lineal es una referencia interpretable; árboles capturan relaciones no lineales; ensembles suelen mejorar robustez a costa de complejidad.","exampleTitle":"Riesgo de churn","example":"Compara baseline lineal, árbol y gradient boosting con la misma validación.","challenge":"Elige dos modelos para un problema binario y explica el trade-off.","quiz":{"question":"¿Cuál es la idea clave de modelos supervisados?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm3','data-science','mid-senior','Modelos no supervisados','Clustering y reducción de dimensionalidad.','Quiz',6,20,3,'{"objective":"Usar clustering y reducción de dimensionalidad para explorar estructura sin una etiqueta objetivo.","explanation":"K-means agrupa por distancia y requiere elegir k. PCA busca componentes que expliquen variabilidad. Ninguno “descubre la verdad” sin interpretación de negocio.","exampleTitle":"Segmentación","example":"Agrupa clientes por frecuencia, gasto y recencia; después perfila cada cluster.","challenge":"¿Qué revisarías para decidir si los clusters son útiles?","quiz":{"question":"¿Cuál es la idea clave de modelos no supervisados?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm4','data-science','mid-senior','Validación de modelos','Evita leakage y mide generalización.','Quiz',6,20,4,'{"objective":"Diseñar validaciones que estimen desempeño real y eviten leakage.","explanation":"Separar entrenamiento y evaluación no basta: en datos temporales hay que respetar el orden temporal; en datasets pequeños puede usarse cross-validation.","exampleTitle":"Forecast","example":"Entrenar con enero-junio y validar en julio-septiembre evita usar futuro para predecir pasado.","challenge":"Identifica un ejemplo de leakage en una variable calculada con datos posteriores al evento.","quiz":{"question":"¿Cuál es la idea clave de validación de modelos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm5','data-science','mid-senior','Métricas de evaluación','Elige métricas según el problema.','Práctica',6,20,5,'{"objective":"Elegir métricas alineadas con el coste de errores y el objetivo del negocio.","explanation":"Accuracy puede ocultar fallos en clases minoritarias. Precision, recall, F1, ROC-AUC, MAE y RMSE responden preguntas diferentes.","exampleTitle":"Fraude","example":"Si perder un fraude es muy costoso, recall puede ser prioritario aunque aumenten falsos positivos.","challenge":"Selecciona una métrica para un detector de fraude y explica el coste asociado.","quiz":{"question":"¿Qué métrica combina precision y recall?","options":["F1-score","R²","MAE","MAPE"],"correctIndex":0,"explanation":"F1 es la media armónica de precision y recall."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm6','data-science','mid-senior','Pipelines de machine learning','Encadena transformación, entrenamiento y evaluación.','Ordenar',6,20,6,'{"objective":"Encadenar transformaciones y modelo de forma reproducible.","explanation":"Un pipeline evita que la transformación se aplique de manera distinta entre entrenamiento y producción y reduce riesgo de leakage.","exampleTitle":"Preprocesamiento","example":"imputer → scaler → encoder → model","challenge":"Ordena los pasos para entrenar un modelo con variables numéricas y categóricas.","quiz":{"question":"¿Qué práctica ayuda a evitar leakage durante el preprocesamiento?","options":["Ajustar transformaciones solo con train","Escalar con todo el dataset antes del split","Mezclar train y test","Eliminar el test"],"correctIndex":0,"explanation":"Las transformaciones deben aprenderse solo del conjunto de entrenamiento."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm7','data-science','mid-senior','Interpretabilidad','Explica por qué un modelo toma una decisión.','Caso',6,20,7,'{"objective":"Explicar predicciones a usuarios técnicos y de negocio sin confundir correlación con causalidad.","explanation":"Importancia global ayuda a entender patrones del modelo; explicaciones locales ayudan a entender una predicción concreta.","exampleTitle":"Aprobación de crédito","example":"Una explicación puede mostrar que ingresos y antigüedad contribuyeron a la predicción, pero no prueba causalidad.","challenge":"Distingue una explicación local de una importancia global.","quiz":{"question":"¿Cuál es la idea clave de interpretabilidad?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dsm8','data-science','mid-senior','Proyecto: predicción','Construye un flujo completo de predicción.','Proyecto',6,40,8,'{"objective":"Integrar definición del problema, datos, features, validación, métricas y comunicación.","explanation":"Un proyecto útil no termina en una métrica: documenta supuestos, baseline, errores y cómo se usaría el modelo.","exampleTitle":"Churn end-to-end","example":"problema → dataset → features → split → baseline → modelo → evaluación → recomendación","challenge":"Define los entregables mínimos de un proyecto de predicción.","quiz":{"question":"¿Cuál es la idea clave de proyecto: predicción?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss1','data-science','senior','Diseño de soluciones ML end-to-end','Diseña datos, entrenamiento, serving y feedback.','Arquitectura',6,20,1,'{"objective":"Diseñar arquitectura desde ingestión hasta serving, monitorización y feedback.","explanation":"La arquitectura debe considerar latencia, frecuencia de predicción, seguridad, coste y recuperación ante fallos.","exampleTitle":"Recomendaciones","example":"offline training + feature store + batch/online inference + monitoring","challenge":"Decide cuándo usar inferencia batch frente a online.","quiz":{"question":"¿Cuál es la idea clave de diseño de soluciones ml end-to-end?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss2','data-science','senior','MLOps','Automatiza experimentos, modelos y despliegues.','Arquitectura',6,20,2,'{"objective":"Automatizar ciclo de vida de modelos, datos y experimentos.","explanation":"MLOps conecta versionado, testing, registro de modelos, despliegue y monitorización. El objetivo es reproducibilidad y operación segura.","exampleTitle":"Release de modelo","example":"commit → tests → train → evaluate → registry → deploy → monitor","challenge":"Define tres gates antes de desplegar un modelo.","quiz":{"question":"¿Cuál es la idea clave de mlops?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss3','data-science','senior','Monitorización de modelos','Define señales técnicas y de negocio.','Práctica',6,20,3,'{"objective":"Detectar degradación técnica y de negocio después del despliegue.","explanation":"Monitoriza latencia, errores, distribución de inputs, calidad cuando hay etiquetas y métricas de negocio.","exampleTitle":"Modelo de fraude","example":"alerta de latencia + drift de features + tasa de falsos positivos","challenge":"Selecciona dos señales técnicas y dos de negocio para monitorizar.","quiz":{"question":"¿Cuál es la idea clave de monitorización de modelos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss4','data-science','senior','Drift de datos','Detecta cuándo cambió la distribución que alimenta el modelo.','Caso',6,20,4,'{"objective":"Distinguir cambios en la distribución de entradas de cambios en la relación objetivo.","explanation":"Data drift puede aparecer sin que el modelo falle inmediatamente. Concept drift implica que la relación entre variables y objetivo cambió.","exampleTitle":"Cambio de clientes","example":"Si cambia la distribución de edad, hay drift de datos; si el patrón de fraude cambia, puede haber concept drift.","challenge":"Clasifica un cambio observado como data drift o concept drift.","quiz":{"question":"¿Qué describe data drift?","options":["Cambio en la distribución de entradas","Cambio de contraseña","Más filas siempre","Un fallo de SQL"],"correctIndex":0,"explanation":"Data drift es un cambio en la distribución de los inputs."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss5','data-science','senior','Optimización de modelos','Latencia, coste y calidad como trade-offs.','Código',6,20,5,'{"objective":"Equilibrar calidad, latencia, coste y complejidad.","explanation":"No siempre gana el modelo más preciso. Cuantiza, reduce features, cachea o usa modelos más pequeños cuando el SLA lo exige.","exampleTitle":"API predictiva","example":"Si el modelo tarda 2s y el SLA es 200ms, debes optimizar el serving aunque pierdas una fracción de precisión.","challenge":"Propón dos técnicas para reducir latencia.","quiz":{"question":"¿Cuál es la idea clave de optimización de modelos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss6','data-science','senior','Modelos en producción','Patrones para serving online y batch.','Arquitectura',6,20,6,'{"objective":"Elegir patrones de serving batch, online o streaming según el caso de uso.","explanation":"Batch es eficiente para grandes volúmenes y poca urgencia. Online sirve decisiones interactivas. Streaming responde continuamente a eventos.","exampleTitle":"Scoring diario","example":"Un score de riesgo recalculado cada madrugada puede ser batch.","challenge":"Elige el patrón de serving para recomendaciones en tiempo real.","quiz":{"question":"¿Cuál es la idea clave de modelos en producción?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss7','data-science','senior','Gobierno del dato aplicado a ML','Trazabilidad, acceso y cumplimiento.','Caso',6,20,7,'{"objective":"Asegurar trazabilidad, acceso, calidad, privacidad y uso responsable de datos en ML.","explanation":"El gobierno define ownership, permisos, linaje, retención y controles. En ML también importa saber qué datos entrenaron un modelo.","exampleTitle":"Linaje de features","example":"dataset → transformación → feature → modelo → predicción","challenge":"Enumera cuatro controles que debería tener un sistema ML gobernado.","quiz":{"question":"¿Cuál es la idea clave de gobierno del dato aplicado a ml?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dss8','data-science','senior','Proyecto senior','Diseña un sistema predictivo completo.','Proyecto',6,40,8,'{"objective":"Diseñar una plataforma completa con arquitectura, gobierno, CI/CD, coste y observabilidad.","explanation":"El entregable senior debe justificar trade-offs y definir cómo operará el sistema a largo plazo.","exampleTitle":"Lakehouse empresarial","example":"sources → ingestion → lakehouse → transformations → serving → governance","challenge":"Dibuja las capas y define un SLO para una de ellas.","quiz":{"question":"¿Cuál es la idea clave de proyecto senior?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej1','data-engineering','junior','Qué es la ingeniería de datos','El papel del data engineer en una plataforma moderna.','Concepto',6,20,1,'{"objective":"Entender cómo un data engineer construye sistemas confiables para mover, transformar y servir datos.","explanation":"La ingeniería de datos se ocupa de disponibilidad, calidad, escalabilidad, costes y contratos de datos.","exampleTitle":"Pedidos online","example":"ingesta de eventos → almacenamiento → transformación → warehouse → consumo","challenge":"Identifica qué parte del flujo requiere ingeniería de datos y por qué.","quiz":{"question":"¿Cuál es la idea clave de qué es la ingeniería de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej2','data-engineering','junior','SQL básico','SELECT, WHERE, GROUP BY y JOIN con datos reales.','SQL',6,20,2,'{"objective":"Consultar datos con SELECT, WHERE, GROUP BY y JOIN.","explanation":"SQL permite expresar qué datos necesitas sin describir paso a paso cómo recorrerlos.","exampleTitle":"Ventas","example":"SELECT country, SUM(revenue) FROM sales GROUP BY country;","challenge":"Escribe una consulta que calcule ventas por país.","quiz":{"question":"¿Qué cláusula filtra filas antes de agrupar?","options":["WHERE","GROUP BY","ORDER BY","HAVING"],"correctIndex":0,"explanation":"WHERE filtra filas antes de la agregación."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej3','data-engineering','junior','Modelado de datos básico','Diseña tablas pensando en consultas y mantenimiento.','Práctica',6,20,3,'{"objective":"Diseñar tablas pensando en claves, relaciones, consistencia y consultas.","explanation":"Un buen modelo reduce ambigüedad y facilita mantenimiento. Define entidades, claves primarias y relaciones antes de optimizar.","exampleTitle":"Clientes y pedidos","example":"customers(id) y orders(id, customer_id) representan una relación uno-a-muchos.","challenge":"Diseña las tablas mínimas para clientes y pedidos.","quiz":{"question":"¿Cuál es la idea clave de modelado de datos básico?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej4','data-engineering','junior','ETL vs ELT','Elige el patrón adecuado según el contexto.','Quiz',6,20,4,'{"objective":"Elegir dónde y cuándo transformar datos según arquitectura y necesidades.","explanation":"ETL transforma antes de cargar; ELT carga primero y transforma dentro del destino analítico. La elección depende de capacidad, gobernanza y latencia.","exampleTitle":"Warehouse cloud","example":"raw → warehouse → SQL transformations es un patrón ELT común.","challenge":"Elige ETL o ELT para una plataforma analítica cloud y justifica.","quiz":{"question":"¿En ELT dónde suele ocurrir la transformación?","options":["En el destino analítico","Antes de extraer","Solo en Excel","En el navegador"],"correctIndex":0,"explanation":"ELT carga primero y transforma dentro del destino."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej5','data-engineering','junior','Python para datos','Automatiza transformaciones con Python.','Código',6,20,5,'{"objective":"Usar Python para automatizar extracción, validación y transformación.","explanation":"Python es útil para integrar APIs, procesar archivos y orquestar lógica que sería incómoda solo con SQL.","exampleTitle":"CSV diario","example":"leer archivo → validar columnas → normalizar fechas → escribir salida","challenge":"Define una validación que detenga el pipeline si falta una columna obligatoria.","quiz":{"question":"¿Cuál es la idea clave de python para datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej6','data-engineering','junior','Introducción a cloud','Compute, storage y servicios gestionados.','Concepto',6,20,6,'{"objective":"Distinguir compute, storage, networking y servicios gestionados.","explanation":"Cloud permite aprovisionar recursos bajo demanda. En datos son comunes object storage, warehouses, compute distribuido y servicios de identidad.","exampleTitle":"Data lake cloud","example":"object storage para raw + warehouse para consumo analítico.","challenge":"Relaciona cada necesidad con un servicio cloud conceptual: almacenamiento, cómputo e identidad.","quiz":{"question":"¿Cuál es la idea clave de introducción a cloud?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej7','data-engineering','junior','Data warehouses','Cómo almacenar datos analíticos de forma eficiente.','Arquitectura',6,20,7,'{"objective":"Entender cómo un warehouse sirve análisis a escala.","explanation":"Los warehouses optimizan almacenamiento y consulta analítica, con separación de cómputo/almacenamiento en muchos servicios modernos.","exampleTitle":"Tabla de ventas","example":"particionar o clustering por fechas y usar modelos dimensionales puede mejorar consultas.","challenge":"Explica por qué un warehouse no es simplemente una base transaccional.","quiz":{"question":"¿Cuál es la idea clave de data warehouses?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dej8','data-engineering','junior','Primer pipeline','Construye un pipeline sencillo de extremo a extremo.','Proyecto',6,40,8,'{"objective":"Construir un flujo reproducible desde una fuente hasta un destino.","explanation":"Un pipeline necesita extracción, validación, transformación, carga y observabilidad básica.","exampleTitle":"CSV a warehouse","example":"extract → validate → transform → load → log","challenge":"Ordena las etapas de un pipeline y define un control de calidad.","quiz":{"question":"¿Cuál es la idea clave de primer pipeline?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem1','data-engineering','mid-senior','SQL avanzado','CTEs, ventanas y consultas analíticas complejas.','SQL',6,20,1,'{"objective":"Resolver consultas complejas con CTEs, ventanas y subconsultas.","explanation":"Las funciones ventana calculan métricas sobre conjuntos relacionados sin perder el detalle de cada fila.","exampleTitle":"Top cliente por país","example":"ROW_NUMBER() OVER(PARTITION BY country ORDER BY revenue DESC)","challenge":"Usa una función ventana para obtener el cliente número 1 por país.","quiz":{"question":"¿Qué función ventana asigna un ranking dentro de cada grupo?","options":["ROW_NUMBER","COUNT DISTINCT","DROP","UNION"],"correctIndex":0,"explanation":"ROW_NUMBER puede numerar filas dentro de una partición."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem2','data-engineering','mid-senior','PySpark','Procesa grandes datasets de forma distribuida.','Código',6,20,2,'{"objective":"Procesar grandes volúmenes con DataFrames distribuidos.","explanation":"Spark divide el trabajo entre ejecutores. Conviene minimizar shuffles, seleccionar columnas temprano y preferir transformaciones eficientes.","exampleTitle":"Ventas masivas","example":"select → filter → groupBy → agg","challenge":"Identifica una operación que puede provocar un shuffle costoso.","quiz":{"question":"¿Cuál es la idea clave de pyspark?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem3','data-engineering','mid-senior','Procesamiento batch','Diseña cargas robustas y repetibles.','Arquitectura',6,20,3,'{"objective":"Diseñar cargas periódicas idempotentes, reintentables y observables.","explanation":"Batch procesa ventanas de datos. Una carga robusta registra checkpoints, controla duplicados y puede repetirse sin corromper el destino.","exampleTitle":"Carga nocturna","example":"partición por fecha + merge/upsert + métricas de filas","challenge":"Diseña una estrategia para reejecutar una partición fallida.","quiz":{"question":"¿Cuál es la idea clave de procesamiento batch?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem4','data-engineering','mid-senior','Data lakes','Organiza datos crudos y procesados.','Concepto',6,20,4,'{"objective":"Organizar datos crudos y procesados con metadatos y reglas de acceso.","explanation":"Un lake conserva datos a distintos niveles de procesamiento. Conviene separar raw, cleaned y curated y definir formatos y contratos.","exampleTitle":"Capas medallion","example":"bronze → silver → gold","challenge":"Explica qué responsabilidad tendría cada capa.","quiz":{"question":"¿Cuál es la idea clave de data lakes?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem5','data-engineering','mid-senior','Orquestación de pipelines','Define dependencias, retries y scheduling.','Práctica',6,20,5,'{"objective":"Coordinar tareas, dependencias, retries y calendarios.","explanation":"Un orquestador convierte scripts aislados en workflows observables. Debe manejar fallos y evitar ejecutar tareas cuando sus dependencias no están listas.","exampleTitle":"DAG de ventas","example":"extract → validate → transform → load → quality_check","challenge":"Define dos retries y una condición de fallo para un DAG.","quiz":{"question":"¿Cuál es la idea clave de orquestación de pipelines?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem6','data-engineering','mid-senior','Calidad del dato','Valida frescura, completitud y consistencia.','Caso',6,20,6,'{"objective":"Medir frescura, completitud, unicidad, validez y consistencia.","explanation":"La calidad se convierte en reglas verificables. Una alerta útil indica qué dataset falló, qué regla y qué impacto tiene.","exampleTitle":"Pedidos diarios","example":"order_id not null, unique; amount >= 0; load within SLA","challenge":"Escribe tres reglas para una tabla de pedidos.","quiz":{"question":"¿Cuál es la idea clave de calidad del dato?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem7','data-engineering','mid-senior','Particionado y optimización','Reduce coste y tiempo de consulta.','Código',6,20,7,'{"objective":"Reducir bytes leídos y coste mediante particionado, clustering y formatos columnares.","explanation":"Particionar por una columna usada frecuentemente en filtros puede evitar escanear datos innecesarios. Demasiadas particiones pequeñas también perjudican.","exampleTitle":"Eventos por fecha","example":"partition by event_date y parquet puede reducir lecturas.","challenge":"Elige una clave de partición y explica el riesgo de sobreparticionar.","quiz":{"question":"¿Cuál es la idea clave de particionado y optimización?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dem8','data-engineering','mid-senior','Proyecto: pipeline batch','Construye un pipeline batch observable y fiable.','Proyecto',6,40,8,'{"objective":"Integrar ingesta, transformación, calidad, orquestación y observabilidad.","explanation":"Un pipeline profesional debe tener contrato de entrada, estrategia de reintento, controles de calidad y métricas operativas.","exampleTitle":"Pedidos diarios","example":"source → landing → transform → warehouse → quality → alerting","challenge":"Define el SLA y tres métricas de operación.","quiz":{"question":"¿Cuál es la idea clave de proyecto: pipeline batch?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des1','data-engineering','senior','Arquitectura lakehouse','Combina flexibilidad de lake y rendimiento analítico.','Arquitectura',6,20,1,'{"objective":"Combinar almacenamiento flexible de lake con capacidades transaccionales y analíticas.","explanation":"Un lakehouse busca una fuente de datos común con formatos abiertos, gobernanza y rendimiento para analítica y ML.","exampleTitle":"Plataforma unificada","example":"object storage + tablas ACID + catálogo + compute","challenge":"Explica qué problema intenta resolver un lakehouse.","quiz":{"question":"¿Cuál es la idea clave de arquitectura lakehouse?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des2','data-engineering','senior','Diseño de plataformas de datos','Define dominios, contratos y capas.','Arquitectura',6,20,2,'{"objective":"Diseñar dominios, contratos, capas y responsabilidades para una plataforma escalable.","explanation":"Una plataforma debe ofrecer caminos seguros y repetibles para productores y consumidores de datos.","exampleTitle":"Data platform","example":"ingestión, storage, transformation, serving, governance, observability","challenge":"Define dos capacidades de plataforma que reduzcan trabajo duplicado.","quiz":{"question":"¿Cuál es la idea clave de diseño de plataformas de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des3','data-engineering','senior','CI/CD para pipelines','Automatiza testing y despliegues.','Código',6,20,3,'{"objective":"Aplicar integración continua y despliegue automatizado a código y workflows de datos.","explanation":"Los tests de SQL, Python, contratos y calidad deben ejecutarse antes de promover cambios.","exampleTitle":"Pipeline release","example":"pull request → tests → deploy staging → validation → production","challenge":"Elige qué validaciones deben bloquear un release.","quiz":{"question":"¿Cuál es la idea clave de ci/cd para pipelines?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des4','data-engineering','senior','Infraestructura como código','Versiona la infraestructura de tu plataforma.','Código',6,20,4,'{"objective":"Versionar infraestructura con archivos declarativos y revisiones.","explanation":"IaC hace reproducible la creación de buckets, roles, redes y servicios. También permite revisar cambios antes de aplicarlos.","exampleTitle":"Entorno de datos","example":"dev/staging/prod con variables separadas","challenge":"Explica una ventaja de IaC frente a cambios manuales.","quiz":{"question":"¿Cuál es la idea clave de infraestructura como código?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des5','data-engineering','senior','Data governance','Políticas, ownership, catálogo y acceso.','Caso',6,20,5,'{"objective":"Definir ownership, políticas, catálogo, acceso y linaje.","explanation":"Gobernar datos no significa impedir acceso: significa hacerlo explícito, auditable y proporcional al riesgo.","exampleTitle":"Dataset de clientes","example":"owner + clasificación + políticas de acceso + linaje","challenge":"Diseña un mínimo de metadatos para publicar una tabla crítica.","quiz":{"question":"¿Cuál es la idea clave de data governance?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des6','data-engineering','senior','Optimización de costes','Equilibra rendimiento, almacenamiento y consumo.','Caso',6,20,6,'{"objective":"Gestionar coste sin degradar los objetivos de negocio.","explanation":"Los costes vienen de almacenamiento, cómputo, transferencia y consultas. Optimizar filtros, formatos, horarios y capacidad suele tener impacto.","exampleTitle":"Warehouse","example":"evitar SELECT *, particionar tablas y apagar recursos ociosos reduce gasto.","challenge":"Propón tres medidas de ahorro para un warehouse con consultas repetitivas.","quiz":{"question":"¿Cuál es la idea clave de optimización de costes?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des7','data-engineering','senior','Escalabilidad y observabilidad','Diseña para fallos y crecimiento.','Arquitectura',6,20,7,'{"objective":"Diseñar sistemas que crecen y detectar fallos antes de que afecten a usuarios.","explanation":"Escalabilidad horizontal, colas, backpressure y métricas permiten absorber crecimiento. Observabilidad combina logs, métricas y trazas.","exampleTitle":"Ingesta de eventos","example":"throughput, lag, error rate y freshness son señales útiles.","challenge":"Elige cuatro métricas para monitorizar una ingesta streaming.","quiz":{"question":"¿Cuál es la idea clave de escalabilidad y observabilidad?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('des8','data-engineering','senior','Proyecto senior','Arquitectura completa de una plataforma de datos.','Proyecto',6,40,8,'{"objective":"Diseñar una plataforma completa con arquitectura, gobierno, CI/CD, coste y observabilidad.","explanation":"El entregable senior debe justificar trade-offs y definir cómo operará el sistema a largo plazo.","exampleTitle":"Lakehouse empresarial","example":"sources → ingestion → lakehouse → transformations → serving → governance","challenge":"Dibuja las capas y define un SLO para una de ellas.","quiz":{"question":"¿Cuál es la idea clave de proyecto senior?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj1','data-analysis','junior','Qué es el análisis de datos','Conecta preguntas de negocio con evidencia.','Concepto',6,20,1,'{"objective":"Convertir preguntas de negocio en análisis reproducibles y recomendaciones.","explanation":"Un analista debe aclarar objetivo, población, periodo, métrica y decisión antes de abrir una herramienta.","exampleTitle":"Caída de conversión","example":"pregunta → métrica → segmentación → hipótesis → evidencia → acción","challenge":"Transforma “¿por qué bajaron las ventas?” en una pregunta analítica concreta.","quiz":{"question":"¿Cuál es la idea clave de qué es el análisis de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj2','data-analysis','junior','Excel básico/intermedio','Limpia, calcula y resume información.','Práctica',6,20,2,'{"objective":"Usar fórmulas, tablas dinámicas y funciones de búsqueda para explorar datos.","explanation":"Excel sigue siendo útil para prototipos y análisis rápidos si se controla la calidad de los datos.","exampleTitle":"Ventas por región","example":"SUMIFS, XLOOKUP y tablas dinámicas permiten resumir y cruzar información.","challenge":"Construye una tabla dinámica de ventas por región y mes.","quiz":{"question":"¿Cuál es la idea clave de excel básico/intermedio?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj3','data-analysis','junior','SQL básico','Consulta datos para responder preguntas.','SQL',6,20,3,'{"objective":"Consultar datos con SELECT, WHERE, GROUP BY y JOIN.","explanation":"SQL permite expresar qué datos necesitas sin describir paso a paso cómo recorrerlos.","exampleTitle":"Ventas","example":"SELECT country, SUM(revenue) FROM sales GROUP BY country;","challenge":"Escribe una consulta que calcule ventas por país.","quiz":{"question":"¿Qué cláusula filtra filas antes de agrupar?","options":["WHERE","GROUP BY","ORDER BY","HAVING"],"correctIndex":0,"explanation":"WHERE filtra filas antes de la agregación."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj4','data-analysis','junior','KPIs','Distingue métricas operativas de indicadores estratégicos.','Caso',6,20,4,'{"objective":"Distinguir métricas de actividad de indicadores vinculados a objetivos.","explanation":"Un KPI debe tener definición, fórmula, frecuencia, owner y contexto. Sin definición compartida, comparar KPIs produce discusiones falsas.","exampleTitle":"Conversión","example":"conversion_rate = purchases / sessions","challenge":"Define numerador, denominador y ventana temporal de una tasa de conversión.","quiz":{"question":"¿Qué elemento es imprescindible para que un KPI sea interpretable?","options":["Definición y fórmula","Solo un color","Un emoji","Más decimales"],"correctIndex":0,"explanation":"Sin definición y fórmula no existe una métrica compartida."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj5','data-analysis','junior','Limpieza y transformación','Prepara datasets para análisis.','Práctica',6,20,5,'{"objective":"Preparar datos para análisis sin perder significado ni trazabilidad.","explanation":"Las transformaciones deben ser explícitas y reproducibles: tipos, nombres, joins, deduplicación y reglas de negocio.","exampleTitle":"Clientes","example":"normalizar país, deduplicar email y crear segmento de cliente.","challenge":"Especifica tres transformaciones y cómo validarías cada una.","quiz":{"question":"¿Cuál es la idea clave de limpieza y transformación?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj6','data-analysis','junior','Visualización de datos','Elige una visualización que comunique el insight.','Gráfico',6,20,6,'{"objective":"Aplicar de forma práctica el concepto de visualización de datos en un flujo de trabajo de datos.","explanation":"Visualización de datos es un concepto del nivel correspondiente. En esta lección se practica cómo tomar una decisión técnica, validar el resultado y documentar el criterio. El foco está en usarlo con datos reales, no en memorizar definiciones.","exampleTitle":"Ejemplo aplicado","example":"Para visualización de datos, parte de una pregunta concreta, trabaja con un dataset pequeño y comprueba el resultado antes de escalar la solución.","challenge":"Diseña una pequeña tarea donde puedas aplicar visualización de datos y define cómo sabrás que el resultado es correcto.","quiz":{"question":"¿Cuál es la idea clave de visualización de datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj7','data-analysis','junior','Introducción a Power BI','Construye un modelo y una vista inicial.','BI',6,20,7,'{"objective":"Comprender dataset, modelo, medidas y visuales en un flujo BI.","explanation":"Power BI separa datos, modelo semántico y reportes. Un buen modelo facilita medidas consistentes y filtros correctos.","exampleTitle":"Modelo de ventas","example":"fact_sales + dim_date + dim_product + dim_customer","challenge":"Explica por qué una dimensión de fecha es útil en un modelo analítico.","quiz":{"question":"¿Cuál es la idea clave de introducción a power bi?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('daj8','data-analysis','junior','Primer dashboard','Entrega un dashboard de negocio claro.','Proyecto',6,40,8,'{"objective":"Diseñar un dashboard con una pregunta clara, KPIs y visuales que permitan actuar.","explanation":"Un dashboard no es un collage. Debe priorizar la decisión, mostrar contexto y evitar gráficos redundantes.","exampleTitle":"Ventas ejecutivas","example":"KPI cards + tendencia + ranking de regiones + detalle filtrable","challenge":"Elige cuatro componentes para un dashboard de ventas mensual.","quiz":{"question":"¿Cuál es la idea clave de primer dashboard?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam1','data-analysis','mid-senior','SQL analítico','Ventanas, cohortes y comparativas temporales.','SQL',6,20,1,'{"objective":"Resolver análisis temporales, rankings y cohortes con SQL.","explanation":"Funciones ventana y fechas permiten comparar periodos y construir métricas por usuario sin perder granularidad.","exampleTitle":"Retención","example":"MIN(signup_date) como cohort_date y meses desde alta.","challenge":"Diseña una consulta conceptual para retención mensual por cohorte.","quiz":{"question":"¿Cuál es la idea clave de sql analítico?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam2','data-analysis','mid-senior','Modelado dimensional','Construye modelos estrella para BI.','Arquitectura',6,20,2,'{"objective":"Diseñar esquemas estrella con hechos y dimensiones.","explanation":"La tabla de hechos contiene eventos medibles; dimensiones aportan contexto. La granularidad debe estar definida explícitamente.","exampleTitle":"Ventas","example":"fact_sales a nivel de línea de pedido; dim_product y dim_date como dimensiones.","challenge":"Define la granularidad de un fact de ventas y dos dimensiones.","quiz":{"question":"¿Qué contiene principalmente una tabla de hechos?","options":["Eventos medibles a una granularidad definida","Solo nombres de usuarios","Configuración del dashboard","Contraseñas"],"correctIndex":0,"explanation":"Los hechos representan eventos o medidas y deben tener una granularidad clara."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam3','data-analysis','mid-senior','DAX básico/intermedio','Crea medidas y cálculos robustos.','Código',6,20,3,'{"objective":"Crear medidas DAX con contexto de filtro y tiempo.","explanation":"Una medida se evalúa según el contexto del reporte. CALCULATE modifica ese contexto y es central para métricas analíticas.","exampleTitle":"Ventas YTD","example":"CALCULATE([Ventas], DATESYTD(dim_date[date]))","challenge":"Explica qué cambia cuando una medida se evalúa bajo un filtro de región.","quiz":{"question":"¿Qué función DAX se usa para modificar contexto de filtro?","options":["CALCULATE","COUNT","FORMAT","IFERROR"],"correctIndex":0,"explanation":"CALCULATE modifica el contexto de evaluación de una medida."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam4','data-analysis','mid-senior','Storytelling con datos','Construye una narrativa basada en evidencia.','Caso',6,20,4,'{"objective":"Construir una narrativa que conecte evidencia con una decisión.","explanation":"Una historia útil presenta contexto, cambio, causa plausible, impacto y siguiente acción, evitando adornar datos.","exampleTitle":"Caída de conversión","example":"contexto → descenso → segmento afectado → hipótesis → acción","challenge":"Escribe un titular que describa un insight sin exagerarlo.","quiz":{"question":"¿Cuál es la idea clave de storytelling con datos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam5','data-analysis','mid-senior','Diseño de dashboards','Jerarquía visual, interacción y foco.','Diseño',6,20,5,'{"objective":"Aplicar jerarquía visual, interacción y foco para facilitar decisiones.","explanation":"La información más importante debe ser visible primero. Filtros y drill-down deben ayudar a investigar, no añadir ruido.","exampleTitle":"Dashboard de operaciones","example":"KPI → tendencia → diagnóstico → detalle","challenge":"Propón un orden visual para investigar una caída de ventas.","quiz":{"question":"¿Cuál es la idea clave de diseño de dashboards?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam6','data-analysis','mid-senior','Análisis de cohortes','Analiza retención y comportamiento.','Práctica',6,20,6,'{"objective":"Comparar grupos de usuarios según fecha de alta o evento inicial.","explanation":"Las cohortes permiten distinguir crecimiento por adquisición de cambios reales en retención.","exampleTitle":"Cohortes mensuales","example":"cohort month × months since signup → retention rate","challenge":"Explica por qué comparar usuarios nuevos y antiguos sin cohortes puede ser engañoso.","quiz":{"question":"¿Qué permite comparar una cohorte?","options":["Usuarios con un mismo evento de inicio","Solo países","Tipos de gráfico","Contraseñas"],"correctIndex":0,"explanation":"Una cohorte agrupa usuarios por un evento inicial compartido."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam7','data-analysis','mid-senior','Análisis de ventas','Encuentra drivers, anomalías y oportunidades.','Caso',6,20,7,'{"objective":"Identificar drivers, mix, anomalías y oportunidades en ventas.","explanation":"Separar volumen, precio, mix y estacionalidad ayuda a evitar conclusiones simplistas.","exampleTitle":"Revenue bridge","example":"revenue = orders × average_order_value","challenge":"Diseña un análisis para explicar una caída de revenue.","quiz":{"question":"¿Cuál es la idea clave de análisis de ventas?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('dam8','data-analysis','mid-senior','Proyecto: dashboard de negocio','Construye un dashboard accionable.','Proyecto',6,40,8,'{"objective":"Integrar modelado, SQL/DAX, visualización y storytelling en un producto analítico.","explanation":"El proyecto debe tener audiencia, decisiones, definiciones de métricas y validaciones.","exampleTitle":"Dashboard comercial","example":"objetivo → modelo → medidas → visuales → validación → recomendación","challenge":"Define los entregables y criterios de aceptación de un dashboard.","quiz":{"question":"¿Cuál es la idea clave de proyecto: dashboard de negocio?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das1','data-analysis','senior','Estrategia analítica','Conecta capacidades analíticas con objetivos de negocio.','Estrategia',6,20,1,'{"objective":"Alinear capacidades de datos con decisiones prioritarias del negocio.","explanation":"La estrategia empieza por decisiones y usuarios, no por herramientas. Define casos de uso, métricas, capacidades y roadmap.","exampleTitle":"Estrategia de crecimiento","example":"priorizar adquisición, activación y retención según impacto y factibilidad.","challenge":"Selecciona un caso de uso analítico y define su decisión objetivo.","quiz":{"question":"¿Cuál es la idea clave de estrategia analítica?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das2','data-analysis','senior','Modelos semánticos','Diseña una capa de métricas consistente.','Arquitectura',6,20,2,'{"objective":"Diseñar una capa consistente de entidades, relaciones y métricas reutilizables.","explanation":"El modelo semántico abstrae complejidad técnica y evita que cada equipo calcule indicadores de forma distinta.","exampleTitle":"Revenue","example":"Una medida centralizada de Revenue debe tener definición, granularidad y reglas de filtros.","challenge":"Define tres elementos que documentarías en un modelo semántico.","quiz":{"question":"¿Cuál es la idea clave de modelos semánticos?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das3','data-analysis','senior','Gobierno de métricas','Evita múltiples definiciones de la misma métrica.','Caso',6,20,3,'{"objective":"Establecer definiciones, owners y controles para métricas críticas.","explanation":"Una métrica gobernada tiene nombre, fórmula, fuente, owner, frecuencia y reglas de uso.","exampleTitle":"Active users","example":"Definir exactamente ventana, evento y exclusiones evita cinco versiones del mismo KPI.","challenge":"Crea una ficha mínima para una métrica crítica.","quiz":{"question":"¿Cuál es la idea clave de gobierno de métricas?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das4','data-analysis','senior','Optimización de dashboards','Mejora rendimiento y experiencia.','Práctica',6,20,4,'{"objective":"Mejorar rendimiento, claridad y coste de reportes.","explanation":"Reducir cardinalidad, limitar visuales, optimizar consultas y diseñar agregaciones puede mejorar la experiencia sin perder valor.","exampleTitle":"Reporte ejecutivo","example":"un modelo eficiente y menos visuales redundantes reduce tiempo de carga.","challenge":"Identifica tres causas comunes de un dashboard lento.","quiz":{"question":"¿Cuál es la idea clave de optimización de dashboards?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das5','data-analysis','senior','Analítica avanzada','Experimentación, segmentación y predicción.','Caso',6,20,5,'{"objective":"Aplicar experimentación, segmentación y modelos predictivos para decisiones más sofisticadas.","explanation":"La analítica avanzada necesita hipótesis, diseño experimental y validación; no basta con aplicar un algoritmo.","exampleTitle":"Experimento de pricing","example":"control vs treatment → métrica primaria → intervalo de confianza → decisión","challenge":"Define una métrica primaria para un experimento de pricing.","quiz":{"question":"¿Cuál es la idea clave de analítica avanzada?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das6','data-analysis','senior','Self-service BI','Equilibra autonomía y control.','Arquitectura',6,20,6,'{"objective":"Dar autonomía a usuarios sin perder calidad, seguridad y definiciones comunes.","explanation":"Self-service funciona cuando existen modelos certificados, catálogo, permisos y formación. Sin gobierno, proliferan métricas contradictorias.","exampleTitle":"Modelo certificado","example":"dataset certificado + roles + catálogo + soporte","challenge":"Define tres guardrails para self-service.","quiz":{"question":"¿Cuál es la idea clave de self-service bi?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das7','data-analysis','senior','Data products','Diseña productos de datos con usuarios claros.','Estrategia',6,20,7,'{"objective":"Diseñar datos como productos con usuarios, contratos, SLAs y ownership.","explanation":"Un data product tiene una audiencia clara, documentación, calidad, discoverability y un ciclo de vida.","exampleTitle":"Customer 360","example":"dataset + contrato + owner + SLA + canal de feedback","challenge":"Define quién es el usuario y qué SLA necesita un data product.","quiz":{"question":"¿Cuál es la idea clave de data products?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
insert into public.lessons(id,route_id,level_id,title,description,type,duration,xp,position,content,published) values ('das8','data-analysis','senior','Proyecto senior ejecutivo','Diseña un sistema analítico para dirección.','Proyecto',6,40,8,'{"objective":"Diseñar un sistema analítico ejecutivo con modelo semántico, gobierno y experiencia de decisión.","explanation":"El sistema debe responder preguntas estratégicas con métricas consistentes y drill-down controlado.","exampleTitle":"Executive cockpit","example":"semantic model → governed metrics → dashboard → alerts → decision reviews","challenge":"Define arquitectura y tres decisiones que el sistema debe soportar.","quiz":{"question":"¿Cuál es la idea clave de proyecto senior ejecutivo?","options":["Aplicar el concepto y validar el resultado","Ignorar la calidad","Evitar documentar","Usar la herramienta más compleja"],"correctIndex":0,"explanation":"La buena práctica es aplicar el concepto, validar y documentar."}}'::jsonb,true) on conflict(id) do update set route_id=excluded.route_id,level_id=excluded.level_id,title=excluded.title,description=excluded.description,type=excluded.type,duration=excluded.duration,xp=excluded.xp,position=excluded.position,content=excluded.content,published=excluded.published,updated_at=now();
